export const MANUALS: Readonly<Record<string, string>> = {
  "kho": "# Warehouse Command Center\n\nTrung tâm điều hành kho nguyên phụ liệu. Nguyên tắc vận hành: **đúng hàng · đúng lô · đúng chỗ — không để đứt chuyền**.\n\n---\n\n## 1. Ba khu vực của Command Center\n\nGiống mọi phân hệ trong hệ thống, phần trên cùng chia ba khu vực:\n\n- **Hộp việc cần làm** — phiếu chờ xử lý, xếp theo số ngày tồn đọng.\n- **Chỉ số then chốt** — tồn kho, hàng chờ kiểm, hàng bị khoá.\n- **Cảnh báo** — vật tư sắp thiếu so với nhu cầu của đơn hàng đang chạy.\n\n## 2. Cách hệ thống hiểu \"tồn kho\"\n\nMột mã vật tư ở một vị trí có bốn con số riêng biệt, không được cộng gộp:\n\n- **Thực có** — số lượng đang nằm trong kho.\n- **Đã giữ chỗ** — đã hứa cho đơn hàng cụ thể, chưa xuất.\n- **Đang kiểm** — đã nhận nhưng chưa qua kiểm chất lượng.\n- **Bị khoá** — không dùng được (sai tông màu, quá hạn, chờ xử lý khiếu nại).\n\n**Khả dụng** là số duy nhất được phép hứa cho đơn mới, và nó do hệ thống tự tính:\n\n> Khả dụng = Thực có − Đã giữ chỗ − Đang kiểm − Bị khoá (không xuống dưới 0)\n\nCon số này **không nhập tay được**. Cơ sở dữ liệu tự tính lại mỗi khi một trong bốn số kia đổi, nên không có chuyện hai màn hình hiện hai kết quả khác nhau.\n\n## 3. Định vị hàng\n\nMỗi vị trí trong kho định danh theo ba cấp: **Khu vực — Kệ — Ô**. Một cuộn vải luôn phải có đủ ba cấp mới coi là đã nhập kho. Ghi thiếu cấp nào thì tìm lại bằng mắt, mất hàng giờ.\n\nNgoài vị trí, mỗi cuộn còn mang **số lô** và **tông màu**. Hai cuộn cùng mã vải nhưng khác tông màu thì **không được thay thế cho nhau** — cắt trộn tông là lỗi không sửa được sau khi đã may.\n\n## 4. Luồng nhập hàng\n\n1. **Nhận hàng** — ghi nhận theo phiếu giao của nhà cung cấp.\n2. **Kiểm chất lượng** — vải đưa vào kiểm; số lượng nằm ở cột *Đang kiểm*, chưa được hứa cho ai.\n3. **Nhập kho** — đạt thì chuyển sang *Thực có* và gán vị trí Khu vực — Kệ — Ô.\n4. **Giữ chỗ** — phân bổ cho đơn hàng, số lượng chuyển sang *Đã giữ chỗ*.\n5. **Xuất cho sản xuất** — cấp cho tổ cắt theo phiếu cắt, trừ khỏi *Thực có*.\n\nMọi lần chuyển đều để lại một dòng trong **nhật ký di chuyển**. Không có thao tác nào sửa thẳng số tồn mà không đi qua nhật ký.\n\n## 5. Truy vết ngược\n\nTừ một thùng hàng thành phẩm có thể lần ngược về đúng cuộn vải đã dùng:\n\n> Thùng hàng → Lô xuất → Phiếu cắt → Cuộn vải → Số lô → Nhà cung cấp\n\nKhi khách khiếu nại một lô hàng, đây là chuỗi cần đi để xác định phạm vi ảnh hưởng.\n\n## 6. Chat liên bộ phận\n\nNút **Chat** ở thanh dưới đáy mở khung trao đổi của kho.\n\n- Gõ `@` rồi tên bộ phận để gọi đúng người — thiếu vật tư thì gọi `@md`, nghi ngờ chất lượng thì gọi `@qa`.\n- Đánh dấu **cờ đỏ** cho việc chặn chuyền.\n- Đính kèm ảnh để chứng minh tình trạng hàng ngay tại chỗ.\n- Tin nhắn được lưu trữ, tải lại trang vẫn còn.\n\n---\n\n## Những điều cần nhớ\n\n- Chỉ hứa hàng theo số **Khả dụng**, không bao giờ theo số **Thực có**.\n- Không trộn tông màu, dù cùng mã vải.\n- Không có dữ liệu mẫu. Màn hình trống nghĩa là chưa có dữ liệu thật.\n",
  "md": "# Merchandiser Command Center\n\nBàn làm việc của bộ phận Merchandiser & Thu mua. Toàn bộ vòng đời một đơn hàng — từ lúc khách hỏi giá đến lúc container rời cảng — nằm trong màn hình này.\n\n---\n\n## 1. Ba khu vực của Command Center\n\nKhi mở `/md`, phần trên cùng luôn là ba khu vực điều hành. Chúng trả lời ba câu hỏi khác nhau, đọc theo thứ tự từ trái sang:\n\n- **Hộp việc cần làm** — việc đang chờ chính bạn xử lý, xếp theo số ngày trễ. Việc trễ lâu nhất nằm trên cùng.\n- **Chỉ số then chốt** — số liệu tổng của bộ phận. Bấm vào một thẻ để nhảy thẳng tới tab chứa dữ liệu chi tiết của nó.\n- **Cảnh báo** — điều bất thường cần biết ngay, kể cả khi chưa phải việc của bạn.\n\n**Quy ước số liệu:** `0` nghĩa là thật sự bằng không. Dấu `—` nghĩa là chưa đọc được dữ liệu. Hai thứ này không bao giờ được hiểu lẫn nhau.\n\n## 2. Mười ba tab nghiệp vụ\n\nCác tab xếp theo ba nhóm, đúng trình tự công việc thực tế:\n\n**Nhóm Thương mại** — giai đoạn trước khi có đơn:\n\n- **Khách hàng** — hồ sơ khách, đầu mối liên hệ, điều khoản thanh toán.\n- **Yêu cầu báo giá (RFQ)** — yêu cầu khách gửi sang, kèm hạn trả lời.\n- **Chiết tính giá** — dựng giá FOB/CM từ định mức nguyên phụ liệu và thời gian may.\n\n**Nhóm Triển khai** — giai đoạn có đơn thật:\n\n- **Mã hàng** — thông số kỹ thuật, bảng size, ảnh mẫu.\n- **Đơn hàng (PO)** — danh sách đơn, cửa vào hồ sơ PO 360°.\n- **Vật tư** — nhu cầu nguyên phụ liệu và tình trạng đặt mua.\n- **Sản xuất** — sản lượng theo chuyền, đối chiếu với kế hoạch.\n- **Giao hàng** — lô xuất, chứng từ, ngày tàu chạy.\n\n**Nhóm Phối hợp** — làm việc cùng bộ phận khác:\n\n- **Tài liệu** — tệp đính kèm theo từng đơn.\n- **Thảo luận** — trao đổi gắn với hồ sơ cụ thể.\n- **Yêu cầu thay đổi** — khách đổi thiết kế, đổi số lượng, đổi ngày.\n- **Rủi ro** — điểm rủi ro và biện pháp đối phó.\n- **Nhật ký** — ai sửa gì, lúc nào. Không xoá được.\n\nBiểu đồ nằm **bên dưới** các tab, không nằm trên. Lý do: khi mở màn hình, việc cần làm phải đập vào mắt trước, biểu đồ là thứ xem sau.\n\n## 3. Luồng quản lý một đơn hàng\n\nTrình tự chuẩn:\n\n1. **Nhận RFQ** — tạo yêu cầu báo giá ở tab *Yêu cầu báo giá*, ghi rõ hạn trả lời khách.\n2. **Chiết tính** — sang tab *Chiết tính giá*. Giá vốn dựng từ định mức nguyên phụ liệu (BOM) và thời gian may chuẩn (SAM); sửa một dòng định mức thì giá tự tính lại.\n3. **Lập mã hàng** — chốt giá xong thì tạo mã hàng ở tab *Mã hàng*, kèm bảng size và thông số.\n4. **Mở PO** — tạo đơn ở tab *Đơn hàng*, gắn với mã hàng và khách hàng đã có.\n5. **Theo dõi** — mở **PO 360°** để bám tiến độ tới khi xuất hàng.\n\n## 4. Hồ sơ PO 360°\n\nBấm một dòng ở tab *Đơn hàng* để mở bảng trượt PO 360°. Đây là toàn bộ những gì cần biết về một đơn hàng, chia mười thẻ:\n\n- **Tổng quan** — đơn này đang ở đâu, có kịp không?\n- **Lịch trình T&A** — mốc nào đã qua, mốc nào sắp tới hạn?\n- **Mẫu duyệt** — khách đã duyệt mẫu chưa?\n- **Cấu trúc NPL** — đơn này cần những vật tư gì, định mức bao nhiêu?\n- **Trạng thái NPL** — vật tư đã về kho chưa, đủ chưa?\n- **Tiến độ sản xuất** — chuyền may đã ra được bao nhiêu?\n- **Chất lượng** — tỷ lệ lỗi, kết quả kiểm hàng.\n- **Đóng gói & Xuất hàng** — đóng thùng tới đâu, chứng từ đủ chưa?\n- **Rủi ro** — điểm nào có nguy cơ trễ hoặc lỗi?\n- **Thảo luận & Tài liệu** — trao đổi và tệp gắn với đơn này.\n\nBảng trượt mở **đè lên** danh sách chứ không rời trang. Đóng lại là về đúng vị trí cũ trong danh sách, không mất bộ lọc đang đặt.\n\n## 5. Tìm nhanh\n\nNhấn **Ctrl + K** (hoặc bấm ô tìm kiếm trên thanh đầu trang) để mở bảng lệnh. Gõ mã PO, mã hàng hoặc tên khách để nhảy thẳng tới hồ sơ. Gõ không dấu vẫn ra kết quả có dấu.\n\n## 6. Chat liên bộ phận\n\nNút **Chat** ở thanh dưới đáy mở khung trao đổi của phân hệ đang đứng.\n\n- Gõ `@` rồi tên bộ phận để gọi đúng người. Gõ không dấu vẫn gợi ý đúng.\n- Đánh dấu **cờ đỏ** cho việc cần xử lý ngay; tin có cờ đỏ hiện viền đỏ nổi bật.\n- Đính kèm ảnh bằng nút kẹp giấy. Ảnh tải lên ngay khi chọn, không đợi bấm gửi.\n- Tin nhắn **được lưu trữ**: tải lại trang vẫn còn. Tin mới của người khác hiện ngay, không cần F5.\n\n**Ai đọc được tin của bạn:** Ban giám đốc, Merchandiser và Quản trị hệ thống đọc được mọi hội thoại. Các bộ phận khác chỉ thấy tin do chính họ gửi và tin có `@` gọi tên bộ phận họ. Quyền này do máy chủ quyết định, không phải do giao diện che bớt.\n\n**Khách hàng (Buyer) không bao giờ đọc được chat nội bộ.**\n\n## 7. Trợ lý phân tích\n\nNút **A.I** ở thanh dưới đáy mở trợ lý.\n\nTrợ lý hiện chạy theo **luật nghiệp vụ**, không phải mô hình ngôn ngữ. Nó đọc số liệu thật trong hệ thống và chỉ ra điều bất thường theo các quy tắc đã cài. Nó **không** đoán, không tự viết văn, và không bao giờ dựng ra số liệu không có trong cơ sở dữ liệu.\n\n## 8. Báo cáo\n\nNút **Báo cáo** ở thanh dưới đáy mở bảng số liệu tổng hợp, có nút xuất thành ảnh dọc để gửi Zalo hoặc dán vào email. Ảnh xuất ra đúng bằng khung nhìn, không dư lề trắng.\n\n---\n\n## Những điều cần nhớ\n\n- Không có dữ liệu mẫu trong hệ thống. Màn hình trống nghĩa là chưa có dữ liệu thật.\n- Nhật ký không xoá được — mọi thao tác sửa đều để lại vết.\n- Hội thoại không sửa và không xoá được. Đây là bằng chứng vận hành khi có tranh chấp với khách.\n",
  "tong-quan": "# Hướng dẫn chung — MONICA MOS\n\nNhững quy ước áp dụng cho **mọi** phân hệ trong hệ thống. Đọc một lần là dùng được tất cả các màn hình.\n\n---\n\n## 1. Thanh điều hướng dưới đáy\n\nLuôn hiện ở mọi trang sau khi đăng nhập, gồm năm nút:\n\n- **Bàn làm việc** — về bàn làm việc của chính bộ phận bạn.\n- **Chat** — trao đổi liên bộ phận, có gọi tên bằng `@`.\n- **Báo cáo** — bảng số liệu, xuất được thành ảnh gửi Zalo.\n- **A.I** — trợ lý phân tích theo luật nghiệp vụ.\n- **Hướng dẫn** — chính là trang bạn đang đọc; nội dung đổi theo phân hệ đang mở.\n\nThanh này tự ẩn khi bàn phím ảo bật lên hoặc khi cuộn xuống, và hiện lại khi cuộn lên. Đang mở một khung trượt thì thanh **không** ẩn — nếu ẩn, bạn sẽ bị kẹt trong khung không có lối ra.\n\n## 2. Về trang chủ\n\nBấm **logo Monica** ở góc trái thanh đầu trang để về trang chủ ở bất kỳ đâu.\n\n## 3. Quy ước số liệu\n\nĐây là quy ước quan trọng nhất của toàn hệ thống:\n\n- **`0`** nghĩa là giá trị thật sự bằng không.\n- **`—`** nghĩa là chưa đọc được dữ liệu.\n\nHệ thống **không có dữ liệu mẫu**. Không có màn hình nào dựng số liệu giả để trông cho đầy. Bảng trống nghĩa là chưa ai nhập gì.\n\n## 4. Bố cục chung của một bàn làm việc\n\nMọi phân hệ dựng theo cùng một khuôn:\n\n1. **Command Center** trên cùng — hộp việc cần làm, chỉ số then chốt, cảnh báo.\n2. **Các tab nghiệp vụ** ở giữa — nơi làm việc thật.\n3. **Biểu đồ** dưới cùng — thứ xem sau, không phải thứ nhìn trước.\n\nThẻ chỉ số bấm được: bấm vào là nhảy thẳng tới tab chứa dữ liệu chi tiết của thẻ đó.\n\n## 5. Quyền truy cập\n\nMỗi tài khoản chỉ vào được phân hệ của bộ phận mình. Vai trò gắn ở phía máy chủ, người dùng không tự đổi được.\n\n**Khách hàng (Buyer)** chỉ thấy đơn hàng của chính công ty họ và **không bao giờ** đọc được hội thoại nội bộ. Đây là hàng rào nằm trong cơ sở dữ liệu, không phải phần giao diện che bớt.\n\n## 6. Chat liên bộ phận\n\n- Gõ `@` rồi tên bộ phận để gọi đúng người. Gõ không dấu vẫn gợi ý đúng.\n- **Cờ đỏ** dành cho việc cần xử lý ngay.\n- Đính kèm ảnh bằng nút kẹp giấy; ảnh tải lên ngay khi chọn.\n- Tin nhắn được lưu trữ và đẩy theo thời gian thực.\n\nMỗi phân hệ có kênh riêng: mở chat khi đang ở kho thì đang nói trong kênh kho, không lẫn với kênh Merchandiser.\n\nHội thoại **không sửa và không xoá được**. Đây là bằng chứng vận hành khi có tranh chấp.\n\n## 7. Đăng nhập lần đầu\n\nTài khoản mới bị buộc đổi mật khẩu ngay lần đăng nhập đầu tiên. Đổi xong mới vào được bàn làm việc.\n\n## 8. Khi màn hình báo lỗi\n\nLỗi luôn hiện thành dải màu đỏ kèm nút **Thử lại**. Hệ thống không bao giờ nuốt lỗi rồi hiện màn hình trống như thể mọi thứ bình thường. Thấy dải đỏ thì bấm thử lại trước; vẫn lỗi thì báo quản trị kèm nguyên văn dòng chữ đó.\n",
};

export type ManualSlug = keyof typeof MANUALS;
